package darksafe

import (
	"errors"
	"reflect"
	"testing"
)

// scratch: rollback to an empty historical version (nil and explicit empty
// lists as the published content).
func TestScratchEmptyRollback(t *testing.T) {
	for _, shape := range []string{"nil", "empty"} {
		t.Run(shape, func(t *testing.T) {
			s := NewStore()
			org := "acme-" + shape
			// v1: empty policy set.
			var empty []Policy
			if shape == "empty" {
				empty = []Policy{}
			}
			v1, err := s.Publish(org, 0, empty)
			if err != nil || v1 != 1 {
				t.Fatalf("publish empty v1 = %d, %v", v1, err)
			}
			// v2: an allow policy currently granting access.
			allow := []Policy{allowPolicy("p-allow", "u1", "read", "org/a", false)}
			v2, err := s.Publish(org, 1, allow)
			if err != nil || v2 != 2 {
				t.Fatalf("publish v2 = %d, %v", v2, err)
			}
			req := request(org, "u1", "r1", "org/a", "read")
			if d := s.Decide(org, req); !d.Allowed {
				t.Fatalf("baseline allow decision = %+v", d)
			}

			// Rollback to v1 (empty).
			v3, err := s.Rollback(org, 2, v1)
			if err != nil || v3 != 3 {
				t.Fatalf("rollback to empty v1 = %d, %v; want new version 3", v3, err)
			}
			if got := s.CurrentVersion(org); got != 3 {
				t.Fatalf("current = %d, want 3", got)
			}
			got, err := s.Policies(org, 3)
			if err != nil {
				t.Fatalf("Policies(v3): %v", err)
			}
			if len(got) != 0 {
				t.Fatalf("v3 policies = %+v, want empty", got)
			}
			// Decision on the new version: default deny.
			d := s.Decide(org, req)
			want := Decision{Allowed: false, Reason: "no matching allow policy", Matched: []string{}, Version: 3}
			if !reflect.DeepEqual(d, want) {
				t.Fatalf("post-rollback decision = %+v, want %+v", d, want)
			}
			// Owner role must not change the outcome.
			ownerReq := req
			ownerReq.Subject.Roles = []string{"owner", "org/a:read"}
			if d := s.Decide(org, ownerReq); d.Allowed || d.Version != 3 || d.Reason != "no matching allow policy" {
				t.Fatalf("owner decision = %+v", d)
			}

			// Audit records: publish v1, publish v2, the first allow Decide,
			// rollback v3, deny Decide, owner Decide = 6 records.
			recs, cp, err := s.AuditExport(org, 0)
			if err != nil {
				t.Fatalf("export: %v", err)
			}
			if len(recs) != 6 {
				t.Fatalf("records = %d, want 6", len(recs))
			}
			chg := recs[3].Change
			if recs[3].Kind != AuditPolicyChange || chg == nil {
				t.Fatalf("record 4 = %+v", recs[3])
			}
			if chg.Version != 3 || !chg.RolledBack || chg.SourceVersion != 1 || len(chg.Policies) != 0 {
				t.Fatalf("rollback change = %+v", chg)
			}
			if err := VerifyAudit(org, recs, cp); err != nil {
				t.Fatalf("verify: %v", err)
			}
			// Offline recheck of the post-rollback denial (seq 5).
			review, err := RecheckDecisionOffline(org, recs, cp, 5)
			if err != nil {
				t.Fatalf("offline recheck: %v", err)
			}
			if !review.Consistent {
				t.Fatalf("offline review inconsistent: %+v", review)
			}
			if !reflect.DeepEqual(review.Recomputed, want) {
				t.Fatalf("recomputed = %+v, want %+v", review.Recomputed, want)
			}

			// Failure behavior on the empty target.
			if _, err := s.Rollback(org, 2, 1); !errors.Is(err, ErrVersionConflict) {
				t.Fatalf("stale expected version on empty target err = %v, want ErrVersionConflict", err)
			}
			if _, err := s.Rollback(org, 3, 99); !errors.Is(err, ErrVersionNotFound) {
				t.Fatalf("missing target err = %v, want ErrVersionNotFound", err)
			}
			if got := s.CurrentVersion(org); got != 3 {
				t.Fatalf("current after failures = %d, want 3", got)
			}
		})
	}
}

